const view=document.body.dataset.view;
const isTeacher=view==='teacher';
notesText.push([],[],[]);
titles.push("DDD: коротко");
const extraStates={};
let pseudoShown=false,receiving=false;
const storageKey='ddd-lesson-state-v5-'+view;
const pseudos={2:'Overlaps(other):\n  return Start < other.End\n     && other.Start < End',4:'RoomSchedule.Book(interval, organizer):\n  если другая активная бронь пересекается: отказ\n  создать Booking и добавить в расписание\n  сохранить новую общую версию',6:'CreateBooking(request, currentUser):\n  schedule = repository.Load(request.RoomId)\n  schedule.Book(request.Interval, currentUser.Id)\n  repository.SaveIfVersionMatches(schedule)',7:'Booking.Cancel(actorId):\n  если actorId != OrganizerId: отказ\n  если Status == Canceled: ничего не менять\n  Status = Canceled',8:'В одной транзакции:\n  обновить RoomSchedule, если Version == 7\n  если строка не обновилась: откатить\n  записать бронь; завершить транзакцию',10:'RoomSchedule.Reschedule(id, newInterval, actor):\n  проверить организатора и статус\n  проверить ДРУГИЕ активные брони\n  если время свободно: изменить интервал\n  сохранить с проверкой общей версии'};
function currentIndex(){return lessonOrder.indexOf(scene)}
function timeRange(){const i=currentIndex(),start=lessonMinutes.slice(0,i).reduce((a,b)=>a+b,0),length=lessonMinutes[i];return length?`${start}–${start+length} мин`:'Бонус · после часа'}
function esc(text){return String(text).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;')}
function captureExtras(){const obj=extraStates[scene]||{},el=id=>document.getElementById(id);if(scene===1)obj.words=Array.from(document.querySelectorAll('.wordcard')).map(x=>!x.querySelector('button'));if(scene===2){obj.time=Number(el('time')?.value??90);obj.checked=!el('intervalAnswer')?.classList.contains('hidden')}if(scene===3)obj.changed=el('bookingTime')?.textContent==='12:00–13:00';if(scene===7)obj.answer=!el('stateAnswer')?.classList.contains('hidden');if(scene===9)obj.outbox=!el('outbox')?.classList.contains('hidden');if(scene===10)obj.rules=el('moveRules')?.textContent!=='Сначала ответы группы';extraStates[scene]=obj}
function applyExtras(){const obj=extraStates[scene]||{},el=id=>document.getElementById(id);if(scene===1&&Array.isArray(obj.words)){const definitions=['Место: «Север», 6 человек','Кто занимает место и когда','Начало и конец','Кто может отменить'];document.querySelectorAll('.wordcard').forEach((x,i)=>{if(obj.words[i]&&x.querySelector('button'))x.querySelector('button').outerHTML='<p>'+definitions[i]+'</p>'})}if(scene===2&&obj.time!==undefined){el('time').value=Math.max(0,Math.min(180,Number(obj.time)));interval(el('time').value,!!obj.checked)}if(scene===3&&obj.changed){el('bookingTime').textContent='12:00–13:00';document.querySelector('#stage .sheet button').disabled=true}if(scene===7)el('stateAnswer')?.classList.toggle('hidden',!obj.answer);if(scene===9)el('outbox')?.classList.toggle('hidden',!obj.outbox);if(scene===10&&obj.rules)el('moveRules').innerHTML='Бронь активна<br>Переносит организатор<br>Начало раньше конца<br>Нет пересечений с другими бронями<br>При записи проверяем общую версию'}
function teacherHtml(){const g=teacherGuides[scene];return `<div class="guideHead"><h2>${esc(titles[scene])}</h2><span class="timeBadge">${timeRange()}</span></div><section class="guideSection"><h3>Что сказать</h3><div class="say">${esc(g.say)}</div></section><section class="guideSection"><h3>Что показать</h3><ol>${g.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section><section class="guideSection"><h3>Вопросы и готовые ответы</h3>${g.qa.map(x=>`<div class="qa"><b>${esc(x.q)}</b><p>${esc(x.a)}</p></div>`).join('')}</section><section class="guideSection deep"><h3>Если спросят подробнее</h3><p>${esc(g.extra)}</p></section>${g.sources.length?`<section class="guideSection sourceLinks"><h3>Проверенные источники</h3>${g.sources.map(([name,url])=>`<a target="_blank" rel="noopener" href="${url}">${esc(name)}</a>`).join('')}</section>`:''}<section class="guideSection"><h3>План на 60 минут</h3><div class="plan">${lessonOrder.map((id,i)=>{const start=lessonMinutes.slice(0,i).reduce((a,b)=>a+b,0);return `<a href="#scene=${id}" onclick="go(${i});return false">${i+1}. ${esc(titles[id])}</a><span>${lessonMinutes[i]?`${start}–${start+lessonMinutes[i]}`:'Бонус'}</span>`}).join('')}</div></section><details class="setup"><summary>Как вывести второе окно на проектор</summary><ol><li>Нажми сверху «Открыть проектор».</li><li>Перенеси второе окно на экран проектора.</li><li>Нажми в нём «На весь экран».</li><li>Листай каждое окно отдельно.</li></ol><p>Окна независимы: в конспекте можно читать дальше, пока на проекторе остаётся схема.</p></details>`}
const originalRender=render;
render=function(){const detail=document.getElementById('teacher'),savedScroll=detail.scrollTop;originalRender();if(scene===14){document.getElementById('stage').innerHTML=head('DDD — проектирование вокруг правил','Сначала понимаем работу. Затем строим модель.')+`<div class="splitExplain"><div class="mapbox core"><strong>Правило</strong><p>Одна комната — одна встреча в каждый момент.</p></div><div class="mapbox"><strong>В коде</strong><p>Расписание отклоняет пересекающуюся бронь.</p></div></div>`}if(scene===6){document.getElementById('stage').innerHTML=head('Один запрос: от экрана до записи','Стрелки показывают порядок выполнения.')+`<div class="architectureFlow">${[['Экран / бот','Получает ввод'],['Application','Загружает расписание'],['Domain','Проверяет и меняет бронь'],['Infrastructure','Сохраняет изменения']].map(([a,b],i)=>`<div class="flowNode ${layerStep===i?'active':''}"><span class="stepNo">${i+1}</span><strong>${a}</strong><span>${b}</span></div>`).join('')}</div><div class="splitExplain"><div class="mapbox core">Сайт и бот вызывают одни правила.</div><div class="mapbox">Реализацию базы подключают при запуске.</div></div><div class="controls"><button class="primary" onclick="layerStep=(layerStep+1)%4;render()">Следующий этап запроса</button><button onclick="layerStep=-1;render()">Сбросить</button></div>`+prompt('Мы добавили бота. Нужно ли заново писать проверку занятости комнаты?')}
if(pseudos[scene])document.getElementById('stage').insertAdjacentHTML('beforeend',`<div class="controls"><button onclick="pseudoShown=!pseudoShown;render()">${pseudoShown?'Скрыть псевдокод':'Показать псевдокод'}</button></div>${pseudoShown?`<div class="pseudoLabel">Псевдокод: обсуждаем идею, не запускаем как C#</div><pre class="pseudo">${esc(pseudos[scene])}</pre>`:''}`);
applyExtras();const index=currentIndex();document.getElementById('dots').innerHTML=lessonOrder.map((id,i)=>`<button class="dot ${id===scene?'current':''}" aria-label="${i+1}. ${esc(titles[id])}" ${id===scene?'aria-current="step"':''} title="${esc(titles[id])}" onclick="go(${i})">${i+1}</button>`).join('');document.getElementById('position').textContent=`${index+1} / ${lessonOrder.length} · ${timeRange()} · ${titles[scene]}`;document.getElementById('prev').disabled=index===0;document.getElementById('next').disabled=index===lessonOrder.length-1;document.getElementById('progress').style.width=((index+1)/lessonOrder.length*100)+'%';if(isTeacher){detail.innerHTML=teacherHtml();detail.scrollTop=savedScroll}requestAnimationFrame(fitStage)};
function fitStage(){if(isTeacher)return;const main=document.getElementById('stage');main.style.transform='none';const top=document.querySelector('header').getBoundingClientRect().bottom+16;main.style.top=top+'px';const availableWidth=innerWidth-24,availableHeight=document.querySelector('.bottom').getBoundingClientRect().top-top-16,scale=Math.min(availableWidth/1440,availableHeight/main.offsetHeight,1.5);const factor=Math.max(.2,scale);main.style.transform=`scale(${factor})`;main.style.marginLeft=`${-720*factor}px`}
go=function(index){captureExtras();scene=lessonOrder[Math.max(0,Math.min(lessonOrder.length-1,index))];pseudoShown=false;document.getElementById('teacher').scrollTop=0;render();history.replaceState(null,'',`#scene=${scene}`);window.scrollTo(0,0);sendState()};
document.getElementById('prev').onclick=()=>go(currentIndex()-1);document.getElementById('next').onclick=()=>go(currentIndex()+1);
function snapshot(){captureExtras();return {revision:4,scene,modelStep,layerStep,raceStep,safe,moved,pseudoShown,extraStates:JSON.parse(JSON.stringify(extraStates))}}
function readState(s){if(!s||s.revision!==4||!lessonOrder.includes(s.scene))return false;scene=s.scene;modelStep=Math.max(0,Math.min(4,Number(s.modelStep)||0));layerStep=Math.max(-1,Math.min(3,Number(s.layerStep)||0));raceStep=Math.max(0,Math.min(4,Number(s.raceStep)||0));safe=!!s.safe;moved=!!s.moved;pseudoShown=!!s.pseudoShown;if(s.extraStates&&typeof s.extraStates==='object')Object.assign(extraStates,s.extraStates);return true}
function sendState(){try{localStorage.setItem(storageKey,JSON.stringify(snapshot()))}catch{}}
addEventListener('resize',fitStage);document.addEventListener('fullscreenchange',fitStage);
if(isTeacher)document.getElementById('openProjector').onclick=()=>window.open('index.html','ddd-projector');
document.getElementById('resetLesson').onclick=()=>{Object.keys(extraStates).forEach(k=>delete extraStates[k]);scene=14;modelStep=0;layerStep=-1;raceStep=0;safe=false;moved=false;pseudoShown=false;render();history.replaceState(null,'','#scene=14');sendState()};
scene=14;try{readState(JSON.parse(localStorage.getItem(storageKey)))}catch{}const hash=location.hash.match(/scene=(\d+)/);if(hash&&lessonOrder.includes(Number(hash[1])))scene=Number(hash[1]);render();
